      { key: 'f', action: 'state_clinch', name: 'Clinch', needsFighter: false, text: () => 'Fight state → CLINCH' },
      { key: 'g', action: 'state_ground', name: 'Ground', needsFighter: false, text: () => 'Fight state → GROUND' },
    ],
