import { ACTION_TO_TOOL, successForAction, TOOL_GROUPS, type Target } from '../components/annotate/taxonomy';

/**
 * The subset of Annotate's palette that is actually a training class with a
 * reviewable clip: `needsFighter` point events minus takedown_attempt/
 * takedown_defended/submission_attempt/knockdown (captured but never
 * exported — see ai/eval/README.md's reference table) and every
 * `state_*` mark (a change point, not a per-event clip). Grouping mirrors
 * `TOOL_GROUPS` so this reads the same as the Annotate palette.
 */
export interface TrainingClass {
  action: string;
  name: string;
  group: string;
  /** The Annotate palette's keyboard shortcut for this class (ToolItem.key/.num). */
  key: string;
}

const NOT_A_CLASS = new Set([
  'takedown_attempt',
  'takedown_defended',
  'submission_attempt',
  'knockdown',
]);

export const TRAINING_CLASSES: TrainingClass[] = TOOL_GROUPS.flatMap((g) =>
  g.items
    .filter((it) => it.needsFighter && !NOT_A_CLASS.has(it.action))
    .map((it) => ({ action: it.action, name: it.name, group: g.group, key: (it.num ?? it.key).toUpperCase() })),
);

export const TRAINING_ACTIONS = new Set(TRAINING_CLASSES.map((c) => c.action));

export const CLASS_BY_ACTION: Record<string, TrainingClass> =
  Object.fromEntries(TRAINING_CLASSES.map((c) => [c.action, c]));

/**
 * What `target`/`success` should become when a Training Data QA reviewer
 * retypes an event to `newAction` (EventReview's "Type" dropdown) — mirrors
 * what Annotate's own palette derives the moment a tool is first pressed
----
// Shared action -> category/color/icon vocabulary, used by both the Player
// (predictions or labels, via LiveFeed) and Annotate (labels only). Driven
// entirely by the structured `action` column — never by regexing free text,
// since `description` is no longer populated for anything but `fight_end`.

export type EventCat = 'strike' | 'grapple' | 'state' | 'round' | 'event';

export function categoryForAction(action: string | null): EventCat {
  if (!action) return 'state';
  if (action === 'fight_end' || action === 'submission_attempt') return 'event';
  if (action.startsWith('takedown_') || action === 'clinch_initiated') return 'grapple';
  if (action.startsWith('state_')) return 'state';
  if (action.startsWith('round_')) return 'round';
  return 'strike';
}

export function colorForAction(action: string | null): string {
  if (!action) return 'var(--text-muted)';
  if (action === 'knockdown') return 'var(--f-red)';
  if (action === 'fight_end' || action === 'submission_attempt') return 'var(--purple-600)';
  if (action.startsWith('takedown_') || action === 'clinch_initiated') return 'var(--orange-400)';
  if (action.startsWith('state_')) return 'var(--slate-400)';
  if (action.startsWith('round_')) return 'var(--green-500)';
  return 'var(--text-primary)'; // strikes are the plain case: ink, so orange stays the brand and never sits beside the red corner
}

export function iconForAction(action: string | null): string {
  if (!action) return 'radio_button_checked';
  if (action === 'knockdown') return 'sports_mma';
  if (action === 'fight_end') return 'sports_score';
  if (action === 'submission_attempt') return 'crisis_alert';
  if (action.startsWith('takedown_') || action === 'clinch_initiated') return 'sports_kabaddi';
  if (action.startsWith('state_')) return 'change_circle';
  if (action.startsWith('round_')) return 'timer';
  return 'bolt';
}
